<template>
  <main class="knowledge-admin">
    <header class="kb-heading"><div><span class="eyebrow">校园知识中心</span><h1>知识库与固定问答</h1><p>接入资料、审核内容、挂载查询。让回答有来源，让纠错可追踪。</p></div><el-button type="primary" @click="openBase()">添加知识库</el-button></header>
    <section class="kb-overview" aria-label="知识库概览"><div><span>知识库</span><strong>{{baseLoading && !bases.length ? '—' : bases.length}}</strong><small>内嵌资料、独立库与外部信息源</small></div><div><span>已挂载</span><strong>{{baseLoading && !bases.length ? '—' : mountedCount}}</strong><small>可参与智能体查询</small></div><div><span>知识条目</span><strong>{{baseLoading && !bases.length ? '—' : entryCount}}</strong><small>包含内嵌资料与管理条目</small></div></section>
    <el-alert v-if="baseError" :title="baseError" type="error" :closable="false" show-icon><el-button text @click="loadBases">重试读取知识库</el-button></el-alert>
    <section v-if="collector.available" class="collector-banner"><div><strong>{{collector.engine==='WECHRSS'?'微信读书自动采集 · WechRss':'微信读书自动采集 · WeRSS'}}</strong><p>{{collector.loggedIn?'微信读书已连接，按计划采集；正文通过读取检查后才同步到知识库。':'请扫码连接微信读书。已有公众号已迁移，授权后会自动采集。'}}</p></div><el-tag :type="collector.loggedIn?'success':'warning'">{{collector.loggedIn?'已授权':'等待扫码'}}</el-tag><el-button type="primary" @click="openCollector">{{collector.loggedIn?'管理公众号':'扫码连接微信'}}</el-button><el-button v-if="collector.engine==='WECHRSS'||collector.engine==='WEMP'" @click="openBulk">批量订阅</el-button></section>
    <el-tabs v-model="tab">
      <el-tab-pane label="知识库" name="bases">
        <div class="entry-toolbar base-toolbar"><el-input v-model="baseKeyword" clearable placeholder="查找知识库名称或信息源" aria-label="查找知识库"/><span class="result-count">显示 {{visibleBases.length}} / {{bases.length}} 个知识库</span><el-button :loading="baseLoading" @click="loadBases">刷新列表</el-button></div>
        <div class="base-grid" v-loading="baseLoading"><article v-for="base in visibleBases" :key="base.id" class="base-card">
          <div class="base-title"><h3>{{base.name}}</h3><el-switch :model-value="base.mounted" :disabled="mounting.has(base.id)" :aria-label="base.name+'启停开关'" inline-prompt active-text="启用" inactive-text="关闭" @change="mount(base)"/></div>
          <p>{{base.description || '独立知识库'}}</p><div class="base-stats"><span>{{kindLabels[base.kind]}}</span><el-tag v-if="base.readOnly" size="small" type="info">只读</el-tag><el-tag v-if="base.connection?.simulation" size="small" type="warning">赛事模拟 · v{{base.connection.version}}</el-tag><span>{{base._count?.entries || 0}} 条</span><span>{{base.agentId?'指定智能体':'全局可用'}}</span></div>
          <p v-if="base.connection?.sourcePath" class="kb-source">{{base.connection.sourcePath}}</p><p v-if="base.connection?.tables" class="sync-meta">{{base.connection.tables}} 张表 · {{base.connection.sqliteRecords}} 条数据库记录</p><p v-if="base.connection?.markdownFiles" class="sync-meta">{{base.connection.markdownFiles}} 份 Markdown 知识文件</p><p v-if="base.connection?.derivedFrom" class="sync-meta">同源精简视图：{{base.connection.derivedFrom}}，完整版同时启用时优先检索完整资料。</p>
          <div class="automation-tags"><el-tag v-if="base.aiReviewEnabled" size="small">AI 审核{{policy.reviewEnabled?'已启用':' · 全局关闭'}}</el-tag><el-tag v-if="base.aiSummaryEnabled" size="small">AI 总结{{policy.summaryEnabled?'已启用':' · 全局关闭'}}</el-tag></div>
          <p v-if="base.kind!=='LOCAL' && base.kind!=='EMBEDDED'" class="sync-meta">同步：{{base.kind==='WECHAT' && base.syncStatus==='SUCCESS' && base.lastSyncSummary?.articles===0 ? '尚无可同步文章' : syncLabels[base.syncStatus] || base.syncStatus}}<br/>{{base.lastSyncAt ? new Date(base.lastSyncAt).toLocaleString():'尚未同步'}}<br/><span v-if="base.syncError">{{base.syncError}}</span></p>
          <div v-if="base.lastSyncSummary" class="sync-detail"><span>{{base.lastSyncSummary.articles}} 篇文章 · 新增 {{base.lastSyncSummary.created}} · 变更 {{base.lastSyncSummary.changed}} · 跳过 {{base.lastSyncSummary.skipped}}</span><p v-if="base.lastSyncSummary.limited">本次按数量上限读取，历史资料继续保留。</p><p v-for="warning in base.lastSyncSummary.warnings" :key="warning">{{warning}}</p></div>
          <div class="base-actions"><el-button v-if="!base.readOnly" size="small" @click="openBase(base)">配置</el-button><el-button size="small" @click="browse(base.id)">条目</el-button><el-button size="small" @click="openShortcuts(base)">快捷按钮</el-button>
            <el-button v-if="base.kind!=='LOCAL' && base.kind!=='EMBEDDED'" size="small" :loading="syncing.has(base.id)" @click="sync(base)">同步</el-button><el-button v-if="automationEnabled(base)" size="small" @click="automate(base.id)">AI 处理</el-button><el-button size="small" type="danger" plain @click="openRemove(base)">移除</el-button></div>
        </article><el-empty v-if="!visibleBases.length && !baseLoading && !baseError" :description="baseKeyword ? '没有匹配的知识库，试试其他名称' : '添加独立知识库、公众号或 PostgreSQL/MySQL 信息源'"/></div>
      </el-tab-pane>
      <el-tab-pane label="条目与固定问答" name="entries">
        <div class="entry-toolbar"><el-input v-model="entryKeyword" clearable maxlength="200" placeholder="搜索标题、问题或答案" aria-label="搜索知识条目" @input="scheduleEntries"/><el-select v-model="baseFilter" clearable placeholder="全部知识库" @change="changeEntryBase"><el-option v-for="b in bases" :key="b.id" :label="b.name" :value="b.id"/></el-select>
          <el-select v-if="entrySections.length" v-model="entrySection" clearable filterable placeholder="按表或文件浏览" @change="reloadEntries"><el-option v-for="section in entrySections" :key="section.value" :label="section.label+' · '+section.count+' 条'" :value="section.value"/></el-select>
          <el-select v-model="statusFilter" clearable placeholder="全部状态" @change="reloadEntries"><el-option label="草稿" value="DRAFT"/><el-option label="已发布" value="APPROVED"/><el-option label="已归档" value="ARCHIVED"/></el-select>
          <el-button :disabled="!editableBases.length" @click="openEntry()">手动添加</el-button><el-button type="primary" :disabled="!editableBases.length" @click="tab='parse'">AI 解析添加</el-button></div>
        <el-alert v-if="entryError" :title="entryError" type="error" :closable="false" show-icon><el-button text @click="loadEntries">重试读取条目</el-button></el-alert>
        <el-table :data="entries" :empty-text="entryError ? '读取失败，请重试' : entryKeyword || baseFilter || statusFilter ? '没有符合筛选条件的条目' : '还没有条目，先手动添加或同步资料'" v-loading="loading"><el-table-column prop="title" label="标题" min-width="180"/><el-table-column prop="base.name" label="知识库" width="160"/>
          <el-table-column label="模式" width="110"><template #default="{row}"><el-tag>{{modeLabels[row.mode]}}</el-tag></template></el-table-column>
          <el-table-column label="状态" width="100"><template #default="{row}">{{statusLabels[row.status]}}</template></el-table-column><el-table-column prop="hitCount" label="命中" width="75"/>
          <el-table-column label="AI 整理" min-width="170"><template #default="{row}"><el-tag v-if="row.aiReviewStatus && row.aiReviewStatus!=='IDLE'" :type="row.aiReviewStatus==='APPROVED'?'success':row.aiReviewStatus==='PROCESSING'?'info':'warning'">{{aiLabels[row.aiReviewStatus] || row.aiReviewStatus}}</el-tag><span v-if="row.summary" class="summary-mark">已生成总结</span><el-tooltip v-if="row.aiReview?.reason" :content="row.aiReview.reason"><span class="sync-meta">{{row.aiReview.reason.slice(0,45)}}</span></el-tooltip></template></el-table-column>
          <el-table-column label="操作" width="240"><template #default="{row}"><el-button v-if="row.readOnly" text @click="readonlyEntry=row">查看</el-button><template v-else><el-button text @click="openEntry(row)">编辑</el-button><el-button text @click="history(row)">版本</el-button><el-button text :type="row.status==='APPROVED'?'warning':'success'" @click="changeStatus(row,row.status==='APPROVED'?'ARCHIVED':'APPROVED')">{{row.status==='APPROVED'?'归档':'发布'}}</el-button></template></template></el-table-column></el-table>
        <el-pagination v-if="total>0" v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="loadEntries"/>
      </el-tab-pane>
      <el-tab-pane label="AI 解析" name="parse">
        <section class="parse-panel"><h3>把自然语言整理为知识条目</h3><p>粘贴通知、办理说明或问答。AI 生成可编辑草稿，发布后才进入查询。</p>
          <el-select v-model="parseBase" placeholder="保存到知识库"><el-option v-for="b in editableBases" :key="b.id" :label="b.name" :value="b.id"/></el-select>
          <el-input v-model="naturalText" type="textarea" :rows="9" maxlength="15000" show-word-limit placeholder="例如：学生问图书馆预约入口时，固定回答……；来源是……"/>
          <el-button type="primary" :loading="parsing" :disabled="!naturalText.trim() || !parseBase" @click="parse">解析成草稿</el-button>
          <article v-for="(draft,i) in drafts" :key="i" class="draft-card"><el-input v-model="draft.title" placeholder="标题"/><el-input v-model="draft.question" placeholder="问题"/><el-input v-model="draft.answer" type="textarea" :rows="4"/>
            <el-select v-model="draft.mode"><el-option label="RAG 查询" value="RAG"/><el-option label="固定答案" value="FIXED"/></el-select><el-button :loading="savingDraft===i" :disabled="savingDraft>=0 || !draft.title?.trim() || !draft.answer?.trim() || !parseBase" @click="saveDraft(draft,i)">保存草稿</el-button></article>
        </section>
      </el-tab-pane>
      <el-tab-pane label="AI 自动化" name="automation"><section class="parse-panel automation-panel"><h3>自动审核与自动总结</h3><p>全局开关和单库开关同时打开时生效。新资料默认是草稿，AI 审核通过的普通资料可自动发布；固定问答、纠错和关键词规则仍须人工发布。</p><el-form label-position="top" :disabled="!auth.can('setting:write') || !policyLoaded || savingPolicy"><div class="form-grid"><el-form-item label="AI 自动审核（全局）"><el-switch v-model="policy.reviewEnabled"/></el-form-item><el-form-item label="AI 自动总结（全局）"><el-switch v-model="policy.summaryEnabled"/></el-form-item></div><el-form-item label="默认整理模型"><el-select v-model="policy.modelId" clearable placeholder="平台默认模型"><el-option v-for="m in models" :key="m.id" :label="m.name" :value="m.id"/></el-select></el-form-item><el-form-item label="每轮处理条目数（每分钟检查一次）"><el-input-number v-model="policy.batchSize" :min="1" :max="5"/></el-form-item><el-button type="primary" :loading="savingPolicy" :disabled="!policyLoaded" @click="savePolicy">保存自动化开关</el-button></el-form><p class="sync-meta">费用计入配置该知识库的管理员额度。总结独立保存，不替换原文；AI 审核会记录理由，但不代表学校官方认证。失败或不确定的内容保留草稿，可在条目中人工审核或重试。</p></section></el-tab-pane>
      <el-tab-pane label="检索试验" name="search"><section class="parse-panel"><h3>发布后验证实际查询</h3><div class="entry-toolbar"><el-select v-model="probeAgent" clearable placeholder="全局知识"><el-option v-for="a in agents" :key="a.id" :value="a.id" :label="a.name"/></el-select><el-input v-model="probeQuery" placeholder="输入学生会问的问题" @keyup.enter="probe"/><el-button type="primary" :loading="probing" :disabled="!probeQuery.trim()" @click="probe">查询</el-button></div>
        <div v-if="probing" class="kb-search-state" role="status">正在查询实际挂载的知识库…</div>
        <el-alert v-if="probeError" :title="probeError" type="error" :closable="false" show-icon/>
        <el-empty v-if="!probing && !probeError && !probeHits.length && !probeFixed && !probeRules.length && !probeMap" :description="probeDone ? '暂未匹配到内容。请检查条目是否已发布、知识库是否已挂载，或换一种问法。' : '输入学生的实际问题，查看固定答案、关键词规则、地图与知识命中。'"/>
        <article v-if="probeFixed" class="draft-card"><el-tag type="success">命中固定答案 · 不调用模型</el-tag><h4>{{probeFixed.title}}</h4><p>{{probeFixed.answer}}</p></article>
        <article v-for="rule in probeRules" :key="rule.id" class="draft-card"><el-tag>命中关键词规则 · {{rule.behavior}}</el-tag><h4>{{rule.title}}</h4><p>{{rule.text || rule.instruction || rule.card?.title || rule.effect}}</p></article><article v-if="probeMap" class="draft-card"><el-tag type="success">命中校园地图</el-tag><p>{{probeMap.answer}}</p></article>
        <div v-for="hit in probeHits" :key="hit.id" class="draft-card"><strong>{{hit.title}}</strong><small> {{hit.provenance?.trust}} · {{hit.provenance?.file}}</small><p>{{hit.summaryShort}}</p><p class="sync-meta">{{hit.matchReasons?.join('；')}}</p></div></section></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="baseVisible" title="知识库配置" width="min(720px,94vw)" :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving"><el-form label-position="top" :disabled="saving">
      <div class="form-grid"><el-form-item label="名称"><el-input v-model="baseForm.name"/></el-form-item><el-form-item label="数据来源"><el-select v-model="baseForm.kind"><el-option v-for="(label,value) in kindLabels" :key="value" :label="label" :value="value"/></el-select></el-form-item></div>
      <el-form-item label="说明"><el-input v-model="baseForm.description"/></el-form-item><el-form-item label="适用智能体"><el-select v-model="baseForm.agentId" clearable placeholder="全局"><el-option v-for="a in agents" :key="a.id" :value="a.id" :label="a.name"/></el-select></el-form-item>
      <template v-if="baseForm.kind==='WECHAT'"><el-form-item label="公众号接入方式"><el-radio-group v-model="wechat.mode"><el-radio-button value="API">采集器 API</el-radio-button><el-radio-button value="RSS">RSS / Atom</el-radio-button></el-radio-group></el-form-item><p class="sync-meta">可使用服务器采集器扫码授权，也可接入外部采集器或完整正文订阅源。</p><template v-if="wechat.mode==='API'"><el-form-item v-if="collector.available" label="使用服务器采集器"><el-switch v-model="wechat.managed"/><span class="sync-meta">扫码授权后自动连接，无需填写地址和令牌。</span></el-form-item><el-form-item label="采集器服务器地址"><el-input v-model="wechat.baseUrl" :disabled="wechat.managed" placeholder="https://collector.example.com"/></el-form-item><el-form-item label="API 路径"><el-input v-model="wechat.apiPath" :disabled="wechat.managed" placeholder="/api/v1/wx"/></el-form-item></template><template v-else><el-form-item label="RSS / Atom 地址"><el-input v-model="wechat.feedUrl" placeholder="https://collector.example.com/feed/公众号编号.xml"/></el-form-item><el-form-item label="公众号名称"><el-input v-model="wechat.accountName" maxlength="120"/></el-form-item></template><el-form-item v-if="!wechat.managed || wechat.mode!=='API'" :label="wechat.mode==='API'?'访问令牌（编辑时留空保留）':'访问令牌（可选，编辑时留空保留）'"><el-input v-model="basePassword" type="password" show-password autocomplete="new-password" maxlength="4000"/></el-form-item><template v-if="wechat.mode==='API'"><div class="entry-toolbar"><el-input v-model="accountKeyword" placeholder="公众号名称关键词"/><el-button :loading="readingAccounts" @click="readAccounts">读取已订阅公众号</el-button></div><el-form-item label="选择公众号（最多 10 个）"><el-select v-model="wechat.accountIds" multiple filterable :multiple-limit="10" placeholder="先读取采集器公众号列表"><el-option v-for="a in accountOptions" :key="a.id" :label="a.name" :value="a.id"/></el-select></el-form-item>
        <div class="wechat-manual"><el-input v-model="manualAccountId" placeholder="采集器公众号 ID" maxlength="150"/><el-input v-model="manualAccountName" placeholder="显示名称" maxlength="120"/><el-button :disabled="!manualAccountId.trim() || wechat.accountIds.length>=10" @click="addAccount">添加到列表</el-button></div>
        <p class="sync-meta">公众号 ID 来自采集器，不能用名称或微信号代替。已选列表随配置保存。</p>
        <div class="wechat-selected"><el-tag v-for="id in wechat.accountIds" :key="id" closable @close="wechat.accountIds=wechat.accountIds.filter(v=>v!==id)">{{accountOptions.find(a=>a.id===id)?.name || id}} · {{id}}</el-tag></div>
      </template><el-form-item label="每次最多同步文章数（多公众号平均分配）"><el-input-number v-model="wechat.maxArticles" :min="Math.max(1,wechat.mode==='API'?wechat.accountIds.length:1)" :max="100"/></el-form-item><p class="sync-meta">仅导入完整正文和原文链接；没有正文的文章会跳过。同步窗口之外的历史文章保留。</p>
      <section v-if="wechat.managed && wechat.mode==='API'" class="wechat-test-result" aria-label="公众号采集进度"><h4>定时采集与正文同步</h4><p class="sync-meta">采集器按公众号独立定时更新。测试只读已有正文；自动同步开启后，新文章进入知识库草稿，随后按已有 AI 开关处理。</p><el-button type="primary" :loading="collectingWechat" :disabled="!wechat.accountIds.length || collectionBusy || collectionCooling" @click="startWechatCollection">采集最新文章</el-button><el-button :loading="collectionReading" :disabled="!wechat.accountIds.length" @click="pollWechatCollection">刷新采集进度</el-button><el-alert v-if="collectionError" :title="collectionError" type="error" :closable="false" show-icon/><article v-for="a in collections" :key="a.id"><div class="base-title"><strong>{{a.name || wechat.accountNames[a.id] || a.id}}</strong><el-tag :type="a.status==='SUCCEEDED'?'success':['FAILED','AUTH_REQUIRED'].includes(a.status)?'danger':'warning'">{{collectionLabels[a.status] || a.status}}</el-tag></div><p>{{a.message}}</p><p v-if="a.retryAfter && a.retryAfter*1000>collectionClock" class="sync-meta">{{a.status==='RATE_LIMITED'?'已暂停重复请求，本地重试窗口：':'下次可手动采集时间：'}}{{new Date(a.retryAfter*1000).toLocaleString()}}。<template v-if="a.status==='RATE_LIMITED'">微信是否解除限制需届时再确认。</template></p><p v-if="['SUCCEEDED','PARTIAL'].includes(a.status)">本次采集 {{a.collected}} 篇可用正文。</p><div v-if="a.autoCollect!==undefined" class="collector-schedule"><span>自动采集</span><el-switch :model-value="a.autoCollect" :disabled="scheduleSaving===a.id" @change="value=>saveCollectorSchedule(a,!!value,a.intervalMinutes || 360)"/><el-select :model-value="a.intervalMinutes" :disabled="scheduleSaving===a.id" @change="value=>saveCollectorSchedule(a,!!a.autoCollect,Number(value))"><el-option :value="60" label="每小时"/><el-option :value="360" label="每 6 小时"/><el-option :value="720" label="每 12 小时"/><el-option :value="1440" label="每天"/></el-select></div><p v-if="a.autoCollect && a.nextCollectAt" class="sync-meta">下次计划采集：{{new Date(a.nextCollectAt*1000).toLocaleString()}}</p></article><el-form-item label="自动同步到知识库"><el-switch v-model="wechat.autoSync"/><span class="sync-meta">保存后生效；只导入完整正文，保留已有审核与总结开关。</span></el-form-item></section>
      <div class="wechat-test-actions"><el-button :loading="testingWechat" :disabled="readingAccounts" @click="testWechat">测试正文</el-button><span class="sync-meta">测试每个公众号的最新一篇，不写入知识库。</span></div>
      <el-alert v-if="wechatTestError" :title="wechatTestError" type="error" :closable="false" show-icon class="wechat-test-error"/>
      <section v-if="wechatTestResult" class="wechat-test-result" aria-label="公众号测试结果"><h4>测试结果</h4><p>连接成功 · {{wechatTestResult.ready}} / {{wechatTestResult.testedAccounts}} 个来源可读取正文 · {{(wechatTestResult.elapsedMs/1000).toFixed(1)}} 秒</p><p class="sync-meta">{{wechatTestResult.tip}}</p>
        <article v-for="a in wechatTestResult.accounts" :key="a.id"><div class="base-title"><strong>{{a.name}}</strong><el-tag :type="a.status==='READY'?'success':a.status==='FAILED'?'danger':'warning'">{{testStatusLabels[a.status]}}</el-tag></div><small>{{a.id}}</small><p>{{a.message}}</p><template v-if="a.sample"><a :href="a.sample.url" target="_blank" rel="noopener noreferrer">{{a.sample.title}}</a><small v-if="a.sample.published"> · {{a.sample.published}}</small><p class="wechat-excerpt">{{a.sample.excerpt}}</p></template></article>
      </section></template>
      <template v-if="baseForm.kind==='POSTGRES' || baseForm.kind==='MYSQL'"><div class="form-grid"><el-form-item label="主机"><el-input v-model="connection.host"/></el-form-item><el-form-item label="端口"><el-input-number v-model="connection.port" :min="1" :max="65535"/></el-form-item><el-form-item label="数据库"><el-input v-model="connection.database"/></el-form-item><el-form-item label="只读用户名"><el-input v-model="connection.user"/></el-form-item></div>
        <el-form-item label="密码（编辑时留空保留）"><el-input v-model="basePassword" type="password" show-password autocomplete="new-password"/></el-form-item>
